CREATE UNIQUE INDEX uniq_notifications_unread_reminder ON public.notifications USING btree (user_id, type, project_id) WHERE ((is_read = false) AND (type = ANY (ARRAY['rotation.reminder'::text, 'secret.expiry_reminder'::text])))
